      $address = htmlspecialchars($witness[0]['address_en'], ENT_QUOTES, 'UTF-8');

      $htmlDesign .= "
            <li style='padding-left: 10pt; text-indent: 0pt;'>
              <p style='padding-left: 10pt; text-indent: 0pt;'> <strong>Witness " . ($key + 1) . ":</strong></p>
              <p style='padding-left: 10pt; text-indent: 0pt;'>Name: $witnessName</p>
              <p style='padding-left: 10pt; text-indent: 0pt;'>Father's Name: $fatherName</p>
              <p style='padding-left: 10pt; text-indent: 0pt;'>Address: $address</p>
            </li>
            ";
    }
    return $htmlDesign;
  }
