            </p>
          ";
      }
    }
    $sl = 0;
    foreach ($data['party'] as $party) {
      if ($party[0]['party_type_id'] == 5) { // Assuming '24' represents partners
        $sl++;
        $name1 = htmlspecialchars($party[0]['party_full_name_en'], ENT_QUOTES, 'UTF-8');

        // Dynamically add party details
        $htmlDesign .= "
