  public function endorsement($data)
  {
    // pr($data['exempted_party']);
    // pr($data['exempted_identification']);
    // pr($data['exempted_witness']);
    // exit;
    $htmlDesign = "
    <!DOCTYPE html>
	<html lang='en'>

	<head>
    <meta charset='UTF-8'>
    <meta name='viewport' content='width=device-width, initial-scale=1.0'>
    
	</head>";
    // $img =  echo $this->webroot/;
    $htmlDesign .= "
	<body>
    <div class='container'>
        <div class='header'>
		

            <h2 style='text-align:center'>GOVERNMENT OF ASSAM</h2>
            <h3>OFFICE OF THE SUB-REGISTRAR:: {$data['office_name']['office_name_en']}</h3>
            <h3>DISTRICT:: {$data['office_name']['district_name_en']} </h3>
        </div>
        

        <div class='section'>
            <label><strong>Deed Number:</strong></label>
            <span>Mentioned at the top right corner of the Deed.</span>
        </div>

        <div class='section'>
            <label><strong>Date of Registration:</strong></label>
            <span>Mentioned at the top right corner of the Deed.</span>
        </div>";
    $sl = 0;
    foreach ($data['party'] as $party) {
      if ($party[0]['party_type_id'] == 11 || $party[0]['party_type_id'] == 13 || $party[0]['party_type_id'] == 27 || $party[0]['party_type_id'] == 9 || $party[0]['party_type_id'] == 18 || $party[0]['party_type_id'] == 7 || $party[0]['party_type_id'] == 1 || $party[0]['party_type_id'] == 4) { // Assuming '24' represents partners
        $sl++;
        $name1 = htmlspecialchars($party[0]['party_full_name_en'], ENT_QUOTES, 'UTF-8');

        // Dynamically add party details
        // $htmlDesign .= "
        //           <h1 style='padding-left: 10pt; text-indent: 0pt; text-align: left'>
        //            Party $sl:
        //           </h1>

        //           <p style='padding-left: 10pt; text-indent: 0pt; text-align: left'>
        //             Name: $name1
        //           </p>
        //         ";
        $htmlDesign .= "
        <div class='section'>
            <label><strong> 1st Party $sl:</strong></label>
            <span>$name1</span>
        </div>";
      }
    }
    $sl = 0;
    foreach ($data['party'] as $party) {
      if ($party[0]['party_type_id'] == 14 || $party[0]['party_type_id'] == 28 || $party[0]['party_type_id'] == 10 || $party[0]['party_type_id'] == 19 || $party[0]['party_type_id'] == 15 || $party[0]['party_type_id'] == 2 || $party[0]['party_type_id'] == 5 || $party[0]['party_type_id'] == 2) { // Assuming '24' represents partners
        $sl++;
        $name2 = htmlspecialchars($party[0]['party_full_name_en'], ENT_QUOTES, 'UTF-8');

        // Dynamically add party details
        // $htmlDesign .= "
        //           <h1 style='padding-left: 10pt; text-indent: 0pt; text-align: left'>
        //            Party $sl:
        //           </h1>

        //           <p style='padding-left: 10pt; text-indent: 0pt; text-align: left'>
        //             Name: $name1
        //           </p>
        //         ";
        $htmlDesign .= "
      <div class='section'>
            <label><strong>2nd Party $sl:</strong></label>
            <span>$name2</span>
        </div>
";
      }
    }
    foreach ($data['party'] as $party) {
      if ($party[0]['party_type_id'] == 29 || $party[0]['party_type_id'] == 24) { // Assuming '24' represents partners
        $sl++;
        $name3 = htmlspecialchars($party[0]['party_full_name_en'], ENT_QUOTES, 'UTF-8');

        // Dynamically add party details
        // $htmlDesign .= "
        //           <h1 style='padding-left: 10pt; text-indent: 0pt; text-align: left'>
        //            Party $sl:
        //           </h1>

        //           <p style='padding-left: 10pt; text-indent: 0pt; text-align: left'>
        //             Name: $name1
        //           </p>
        //         ";
        $htmlDesign .= "
      <div class='section'>
            <label><strong>Party $sl:</strong></label>
            <span>$name3</span>
        </div>
";
      }
    }
    $htmlDesign .= "<h1>Home Visit Endorsements</h1>";
    $hv_operator = isset($data['hv_operator']) ? $data['hv_operator'] : null;
    $SRO_name = $data['SRO_name'];
    $stamp1_date = $data['stamp1_date'];
    $htmlDesign .= "<div class='endorsement'>
            <h3>Issual of Commission</h3>
            <p>A commission is hereby issued under Section 33(or 38) of the Indian Registration Act.1908 to $hv_operator (Home Visit Operator) for the purpose of inquiring and reporting whether
            this power or document has been executed ";

    foreach ($data['party'] as $party) {
      $htmlDesign .= h($party[0]['party_full_name_en']) . ", ";
    }

    $htmlDesign .= "     
             by whom it purpots to have been executed. 
            </p>
        </div>";

    $htmlDesign .= "
        <div class='signature'>
            <p><strong>Registering officer:</strong> $SRO_name </p>
            <p><strong>Date:</strong>$stamp1_date</p>
        </div>
    </div>
</body>

</html>";
    $hv_address = $data['hv_address'];
    $hv_date =  $data['hv_date'];
    $hv_endorsement = $data['hv_endorsement'];
    $htmlDesign .= "<div class='endorsement'>
            <h3>Commissioner Report</h3>
            <p> $hv_endorsement
            </p>
        </div>";

    $htmlDesign .= "
        <div class='signature'>
            <p><strong>Home Visit Operator:</strong> $hv_operator (Home Visit Operator)</p>
            <p><strong>Date:</strong> $hv_date </p>
        </div>
    </div>
</body>

</html>";


    $htmlDesign .= "<div class='endorsement'>
            <h3>RO Report</h3>
            <p>From the above report, I am satisfied that this power or document has been executed by the above ";
    foreach ($data['party'] as $party) {
      $htmlDesign .= h($party[0]['party_full_name_en']) . ", ";
    }


    $htmlDesign .= " and I accordingly admit it to registration. 
            </p>
        </div>";



    $htmlDesign .= "
        <div class='signature'>
            <p><strong>Registering officer:</strong> $SRO_name </p>
        </div>
    </div>
</body>

</html>";

    return $htmlDesign;
  }
