                margin: 0pt;
            }
            .body-style {
                padding: 10px 20px;
            }
            </style>
            <body class='body-style'>
            <h1 style=' padding-top: 3pt;text-indent: 0pt;text-align: center;font-size: 16px;  padding-bottom: 5pt'><span class='readonly' contenteditable='false'><span class='readonly' contenteditable='false'>
        DISSOLUTION OF PARTNERSHIP DEED	
            <span></h1>";

      $office = isset($data['office_name']['office_name_en']) ? $data['office_name']['office_name_en'] : '';

      $htmlDesign .= "
                <p style='padding-right: 2rem; padding-bottom: 10pt; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
                    <span class='readonly' contenteditable='false'>
                        This Dissolution Of Partnership Deed is made on the date mentioned on the top right corner of the deed at " . htmlspecialchars($office) . " .
                    </span>
                </p>";

      $htmlDesign .= "<h1 style='text-align: center; font-size: 16px; padding-bottom: 20px;'><strong>BETWEEN</strong></h1>";

      $sl = 0;
      $partyNoArr = array(
        1 => "First",
        2 => "Second",
        3 => "Third",
        4 => "Fourth",
        5 => "Fifth",
        6 => "Sixth",
        7 => "Seventh",
        8 => "Eighth",
        9 => "Ninth",
        10 => "Tenth"
      );

      foreach ($data['party'] as $party) {
        if ($party[0]['party_type_id'] == 24) {
          //$partySelltor[] = $party[0]['party_full_name_en']; // Collect names

          $sl += 1;
          $name1 = htmlspecialchars($party[0]['party_full_name_en']);
          $fname1 = htmlspecialchars($party[0]['father_full_name_en']);
          $address1 = htmlspecialchars($party[0]['address_en']);
          $age1 = htmlspecialchars($party[0]['age']);

          if ($sl > 1) {
            $htmlDesign .= "<h1 style='text-align: center; font-size: 16px; padding-bottom: 20px; padding-left: 20px;'><strong>AND</strong></h1>";
          }

          $htmlDesign .= "
                    <p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
                        <span class='readonly' contenteditable='false'>
                            {$sl}.	Mr./Ms. {$name1}, son/daughter of {$fname1}, aged {$age1} years, residing at {$address1}, hereinafter called “Partner {$sl}” or $partyNoArr[$sl] Party; 
                        </span>
                    </p>";
        }
      }

      $htmlDesign .= "<p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left;letter-spacing: 0.8pt;'>
                (Partner 1 and Partner 2 are collectively referred to as “the Partners” and individually as a “Partner”.)
            </p>";

      if (!empty($data['e_deed_party_transaction_details']) && $data['e_deed_party_transaction_details'] !== "NA") {
        foreach ($data['e_deed_party_transaction_details'] as $val) {
          $deedPatnershipDate = isset($val[0]['transaction_date']) ? date('d-m-y', strtotime($val[0]['transaction_date'])) : '';
          $docRegNo = isset($val[0]['doc_reg_no']) ? $val[0]['doc_reg_no'] : '';
          $businessPlace = isset($val[0]['business_place']) ? $val[0]['business_place'] : '';
          $firmName = isset($val[0]['val3']) ? $val[0]['val3'] : '';

          $htmlDesign .= "<br/><br/><p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left;letter-spacing: 0.8pt;'>
                        The Partners executed a Deed of Partnership dated [ " . htmlspecialchars($deedPatnershipDate) . " ], registered as Document No. [ " . htmlspecialchars($docRegNo) . " ] at the Office of the Sub-Registrar, [ " . htmlspecialchars($businessPlace) . " ], carrying on business under the name and style of [ " . htmlspecialchars($firmName) . " ] (hereinafter called “the Firm”). <br/>
                    </p>";
        }
      }

      $htmlDesign .= "<p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
            <span class='readonly' contenteditable='false'>
            B. The Partners have mutually agreed to dissolve the Firm and settle its affairs on the terms and conditions appearing herein.
            </span></p>";

      if (!empty($data['e_deed_party_transaction_details']) && $data['e_deed_party_transaction_details'] !== "NA") {
        foreach ($data['e_deed_party_transaction_details'] as $val) {
          $dissolutionDate = isset($val[0]['date_lll']) ? date('d-m-y', strtotime($val[0]['date_lll'])) : '';

          $htmlDesign .= "<br/> <br/> <p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
                    <span class='readonly' contenteditable='false'>
                        1. DISSOLUTION <br/>
                        1.1 The Partners hereby dissolve the Firm with effect from " . htmlspecialchars($dissolutionDate) . " (the “Dissolution Date”) pursuant to Section 39 of the Indian Partnership Act, 1932.
                    </span>
                    </p>";
        }
      }

      $htmlDesign .= "<p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
            <span class='readonly' contenteditable='false'>
                2. FINAL ACCOUNTS & VALUATION <br/>
                2.1 The books of account of the Firm shall be made up to the Dissolution Date, a balance sheet and profit-and-loss account prepared within [30] days thereof. <br/>
                2.2 All assets and liabilities shall be valued by a Chartered Accountant jointly appointed by the Partners, whose valuation shall be final and binding on the Partners. 
                </span>
                </p>";

      if (!empty($data['e_deed_party_transaction_details']) && $data['e_deed_party_transaction_details'] !== "NA") {
        foreach ($data['e_deed_party_transaction_details'] as $val) {
          $ratioOne = isset($val[0]['val']) ? $val[0]['val'] : '';
          $ratioTwo = isset($val[0]['val2']) ? $val[0]['val2'] : '';

          $htmlDesign .= "<p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
                    <span class='readonly' contenteditable='false'>
                        3. SETTLEMENT OF LIABILITIES <br/>
                        3.1 Out of the Firm’s assets, the Partners shall first pay: a. Third-party debts and liabilities; b. Advances made by any Partner to the Firm; and c. Capital contributed by the Partners. <br/>
                        3.2 Any deficiency shall be borne by the Partners in their profit-sharing ratio, [" . htmlspecialchars($ratioOne) . " : " . htmlspecialchars($ratioTwo) . "], or in such other proportion as may be agreed in writing.
                    </span>
                    </p>";
        }
      }


      $htmlDesign .= "<p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
                        <span class='readonly' contenteditable='false'>
                        4. DISTRIBUTION OF ASSETS <br/>
                            4.1 The residual assets, including goodwill, intellectual property, tenancy rights, and immovable properties, shall be divided between the Partners in the aforesaid ratio unless otherwise mutually agreed. <br/>
                            4.2 Title to any immovable property vested in the Firm shall be conveyed to the Partners by separate registered deeds as necessary. <br/>
                        5. BANK ACCOUNTS <br/>
                            5.1 The Partners shall jointly instruct all bankers of the Firm to close existing accounts and distribute their balances in accordance with Clause 4 above. <br/>
                        6. CONTINUING GUARANTEES <br/>
                            6.1 All continuing guarantees given to any bank or third party on behalf of the Firm are revoked, and the Partners shall obtain letters of release. Each Partner shall indemnify the other against claims arising from guarantees not yet released. <br/>
                            6.2 Each Partner shall be responsible for obtaining the revocation or novation of guarantees where they are the primary obligors. <br/>
                        7. RELEASE & INDEMNITY <br/>
                            Each Partner releases the other from all claims relating to the Firm and agrees to indemnify and keep indemnified the other Partner against all losses, costs, actions, and demands arising from any act or omission of the Firm prior to the Dissolution Date. <br/>
                        8. NOTICES OF DISSOLUTION <br/>
                            8.1 Within 14 days of the Dissolution Date, the Partners shall give public notice of dissolution in one English-language and one vernacular newspaper circulating in the district where the Firm carried on business, as required by Section 72 of the Indian Partnership Act, 1932. Proof of publication shall be retained for record and legal compliance. <br/>
                            8.2 Notice of dissolution shall also be filed with the Registrar of Firms under Section 71 of the Indian Partnership Act, 1932. <br/>
                        9. REGISTRATION OF THIS DEED <br/>
                            Pursuant to Sections 17 & 18 of the Indian Registration Act, 1908, this Deed shall be presented for registration before the Sub-Registrar of [District] within four months of its execution. Stamp duty and registration fees payable hereon under the Indian Stamp Act, 1899 (as amended and as applicable in the State of Assam shall be borne equally by the Partners. <br/>
                        10. COSTS <br/>
                            All costs, charges, and expenses incurred in connection with this Deed—including stamp duty, registration charges, and professional fees—shall be shared equally by the Partners unless otherwise agreed. <br/>
                        11. DISPUTE RESOLUTION (ARBITRATION) <br/>
                            11.1 This Deed shall be governed by and construed in accordance with the laws of India. <br/>
                            11.2 Any dispute or difference arising out of or relating to this Deed shall be referred to arbitration in accordance with the Arbitration & Conciliation Act, 1996. The arbitral tribunal shall comprise a sole arbitrator jointly appointed by the Partners. The seat and venue of arbitration shall be at Guwahati, Assam and the language of proceedings shall be English. <br/>
                            11.3 If the parties fail to appoint an arbitrator within 30 days, the appointment shall be made as per Section 11 of the Arbitration and Conciliation Act, 1996. <br/>
                        12. ENTIRE AGREEMENT <br/>
                            This Deed constitutes the entire agreement between the Partners with respect to its subject matter and supersedes all prior understandings, whether oral or written. <br/>
                        13. AMENDMENTS <br/>
                            No amendment to this Deed shall be valid unless made in writing and signed by all Partners. <br/>
                            </span></p>";

      $additionalText = "";

      // Check if 'additional_data' exists, is an array, and has the expected indexes
      if (!empty($data['additional_data']) && isset($data['additional_data'][0][0]['added_text'])) {
        $additionalText = $data['additional_data'][0][0]['added_text'];
      }

      $htmlDesign .= "<p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
        
              
        <div id='additional' style='padding-left: 5pt;text-indent: 0pt;text-align: left;'>{$additionalText}</div>
        </p>";


      //  $htmlDesign .= " <h1 style='text-align: left; font-size: 16px; padding-bottom: 20px; padding-left: 20px;'><strong>SCHEDULE A<br>
      // (Description of the Mortgaged Property)</strong></h1>";

      $htmlDesign .= " <h1 style=' padding-top: 3pt;text-indent: 0pt;text-align: center;font-size: 16px;  padding-bottom: 5pt'>
                        <span class='readonly' contenteditable='false'><span class='readonly' contenteditable='false'>
                            IN WITNESS WHEREOF <br/>
                        <span></h1>
                        <p style='padding-right: 2rem; padding-left: 2rem; padding-top: 3pt; text-indent: 0pt; text-align: left; letter-spacing: 0.8pt;'>
                            <span class='readonly' contenteditable='false'>
                                The Partners hereunto set their respective hands on the date first written above. <br/>
                            </span>
                        </p>";

      $sl = 0;
      $htmlDesign .= "<ul>";
      foreach ($data['party'] as $party) {

        if ($party[0]['party_type_id'] == 24) {
          //$partySelltor[] = $party[0]['party_full_name_en']; // Collect names

          $sl += 1;
          $name1 = htmlspecialchars($party[0]['party_full_name_en']);
          $fname1 = htmlspecialchars($party[0]['father_full_name_en']);
          $address1 = htmlspecialchars($party[0]['address_en']);
          $age1 = htmlspecialchars($party[0]['age']);

          $htmlDesign .= "
                <li style='padding-left: 10pt; text-indent: 0pt;'>
                    <p style='padding-left: 10pt; text-indent: 0pt;'> <strong>PARTNER . {$sl} . :</strong></p>
                    <p style='padding-left: 10pt; text-indent: 0pt;'>Name: {$name1}</p>
                    <p style='padding-left: 10pt; text-indent: 0pt;'>Address: {$address1}</p>
                </li>";
        }
      }
      $htmlDesign .= "</ul>";

      $htmlDesign .= "<h1 style=' padding-top: 3pt;text-indent: 0pt;text-align: center;font-size: 16px;  padding-bottom: 5pt'><span class='readonly' contenteditable='false'><span class='readonly' contenteditable='false'>
                WITNESSESS <br/>
            <span></h1>";

      $htmlDesign .= "<ul>";
      foreach ($data['witness'] as $key => $witness) {
        $witnessName = htmlspecialchars($witness[0]['witness_full_name_en'], ENT_QUOTES, 'UTF-8');
        $address = htmlspecialchars($witness[0]['address_en'], ENT_QUOTES, 'UTF-8');

        $htmlDesign .= "
                    <li style='padding-left: 10pt; text-indent: 0pt;'>
                    <p style='padding-left: 10pt; text-indent: 0pt;'> <strong>Witness " . ($key + 1) . ":</strong></p>
                    <p style='padding-left: 10pt; text-indent: 0pt;'>Name: $witnessName</p>
                    <p style='padding-left: 10pt; text-indent: 0pt;'>Address: $address</p>
                    </li>
                    ";
      }
      $htmlDesign .= "</ul>";
      return $htmlDesign;
    }
  }

