        foreach ($data['party'] as $party) {
            if ($party[0]['party_type_id'] == 21) {
                // $partySelltor[] = $party[0]['party_full_name_en']; // collect names
                $partySelltor[] = "<span style='font-family: dejavusans;'>" . htmlspecialchars($party[0]['party_full_name_en']) ."</span>";

                $sl++; // increment serial
                $name1 = $party[0]['party_full_name_en'];
